export class TooltipState {
    x = $state(0);
    y = $state(0);
    data = $state(null);
    series = $state([]);
    isHoveringTooltipArea = $state(false);
    isHoveringTooltipContent = $state(false);
    mode;
    show;
    hide;
    constructor(mode, show, hide) {
        this.mode = mode;
        this.show = show;
        this.hide = hide;
    }
}
